pub const AgentRole = enum {
    planner,
    coordinator,
    executor,
    analyst,
    memory_keeper,
    operator,
    observer,

    pub fn parse(text: []const u8) AgentRole {
        if (std.ascii.eqlIgnoreCase(text, "planner")) return .planner;
        if (std.ascii.eqlIgnoreCase(text, "coordinator")) return .coordinator;
        if (std.ascii.eqlIgnoreCase(text, "executor")) return .executor;
        if (std.ascii.eqlIgnoreCase(text, "analyst")) return .analyst;
        if (std.ascii.eqlIgnoreCase(text, "memory_keeper")) return .memory_keeper;
        if (std.ascii.eqlIgnoreCase(text, "operator")) return .operator;
        return .observer;
    }

    pub fn toString(self: AgentRole) []const u8 {
        return switch (self) {
            .planner => "planner",
            .coordinator => "coordinator",
            .executor => "executor",
            .analyst => "analyst",
            .memory_keeper => "memory_keeper",
            .operator => "operator",
            .observer => "observer",
        };
    }
};

