pub const DataValue = union(enum) {
    none,
    boolean: bool,
    integer: i64,
    float: f64,
    text: []u8,

    pub fn clone(self: DataValue, allocator: Allocator) !DataValue {
        return switch (self) {
            .none => .none,
            .boolean => |v| .{ .boolean = v },
            .integer => |v| .{ .integer = v },
            .float => |v| .{ .float = v },
            .text => |v| .{ .text = try allocator.dupe(u8, v) },
        };
    }

    pub fn deinit(self: *DataValue, allocator: Allocator) void {
        switch (self.*) {
            .text => |v| allocator.free(v),
            else => {},
        }
        self.* = .none;
    }

    pub fn isTruthy(self: DataValue) bool {
        return switch (self) {
            .none => false,
            .boolean => |v| v,
            .integer => |v| v != 0,
            .float => |v| v != 0.0,
            .text => |v| v.len > 0,
        };
    }

    pub fn write(self: DataValue, writer: anytype) !void {
        switch (self) {
            .none => try writer.writeAll("none"),
            .boolean => |v| try writer.print("{}", .{v}),
            .integer => |v| try writer.print("{d}", .{v}),
            .float => |v| try writer.print("{d:.6}", .{v}),
            .text => |v| try writer.writeAll(v),
        }
    }

    pub fn toOwnedText(self: DataValue, allocator: Allocator) ![]u8 {
        var list = ArrayList(u8).init(allocator);
        errdefer list.deinit();
        try self.write(list.writer());
        return list.toOwnedSlice();
    }
};

fn dupString(allocator: Allocator, text: []const u8) ![]u8 {
    return allocator.dupe(u8, text);
}

fn dupOptionalString(allocator: Allocator, text: ?[]const u8) !?[]u8 {
    if (text) |value| {
        return try allocator.dupe(u8, value);
    }
    return null;
}

fn trimSpace(text: []const u8) []const u8 {
    return std.mem.trim(u8, text, " \t\r\n");
}

fn parseBoolText(text: []const u8) bool {
    return std.ascii.eqlIgnoreCase(trimSpace(text), "true") or std.mem.eql(u8, trimSpace(text), "1");
}

fn parseValueAuto(allocator: Allocator, text: []const u8) !DataValue {
    const clean = trimSpace(text);
    if (clean.len == 0) return .none;
    if (std.ascii.eqlIgnoreCase(clean, "true") or std.ascii.eqlIgnoreCase(clean, "false")) {
        return .{ .boolean = parseBoolText(clean) };
    }
    if (std.fmt.parseInt(i64, clean, 10)) |v| {
        return .{ .integer = v };
    } else |_| {}
    if (std.fmt.parseFloat(f64, clean)) |v| {
        return .{ .float = v };
    } else |_| {}
    return .{ .text = try allocator.dupe(u8, clean) };
}

fn countTokenMatches(haystack: []const u8, query: []const u8) usize {
    var total: usize = 0;
    var it = std.mem.tokenizeAny(u8, query, " \t\r\n,;:|");
    while (it.next()) |token| {
        if (token.len == 0) continue;
        if (std.mem.indexOf(u8, haystack, token) != null) {
            total += 1;
        }
    }
    return total;
}

