pub const MemoryRecord = struct {
    owner_agent: ?[]u8,
    key: []u8,
    value: DataValue,
    scope: MemoryScope,
    tags: ArrayList([]u8),
    hits: u64,
    created_at_ms: i64,
    updated_at_ms: i64,

    pub fn init(
        allocator: Allocator,
        owner_agent: ?[]const u8,
        scope: MemoryScope,
        key: []const u8,
        value: DataValue,
        tags: []const []const u8,
    ) !MemoryRecord {
        var out = MemoryRecord{
            .owner_agent = try dupOptionalString(allocator, owner_agent),
            .key = try allocator.dupe(u8, key),
            .value = try value.clone(allocator),
            .scope = scope,
            .tags = ArrayList([]u8).init(allocator),
            .hits = 0,
            .created_at_ms = std.time.milliTimestamp(),
            .updated_at_ms = std.time.milliTimestamp(),
        };
        errdefer out.deinit(allocator);
        for (tags) |tag| {
            try out.tags.append(try allocator.dupe(u8, tag));
        }
        return out;
    }

    pub fn deinit(self: *MemoryRecord, allocator: Allocator) void {
        if (self.owner_agent) |owner| allocator.free(owner);
        allocator.free(self.key);
        self.value.deinit(allocator);
        for (self.tags.items) |tag| allocator.free(tag);
        self.tags.deinit();
    }

    pub fn score(self: *const MemoryRecord, query: []const u8) usize {
        var score_value: usize = countTokenMatches(self.key, query);
        switch (self.value) {
            .text => |v| score_value += countTokenMatches(v, query),
            else => {},
        }
        for (self.tags.items) |tag| {
            score_value += countTokenMatches(tag, query);
        }
        if (self.owner_agent) |owner| {
            score_value += countTokenMatches(owner, query);
        }
        return score_value;
    }
};

