pub const MemoryFabric = struct {
    allocator: Allocator,
    records: ArrayList(MemoryRecord),

    pub fn init(allocator: Allocator) MemoryFabric {
        return .{
            .allocator = allocator,
            .records = ArrayList(MemoryRecord).init(allocator),
        };
    }

    pub fn deinit(self: *MemoryFabric) void {
        for (self.records.items) |*record| {
            record.deinit(self.allocator);
        }
        self.records.deinit();
    }

    pub fn put(
        self: *MemoryFabric,
        owner_agent: ?[]const u8,
        scope: MemoryScope,
        key: []const u8,
        value: DataValue,
        tags: []const []const u8,
    ) !void {
        if (self.findLatestIndex(key)) |idx| {
            var record = &self.records.items[idx];
            record.value.deinit(self.allocator);
            record.value = try value.clone(self.allocator);
            record.updated_at_ms = std.time.milliTimestamp();
            if (record.owner_agent) |owner| self.allocator.free(owner);
            record.owner_agent = try dupOptionalString(self.allocator, owner_agent);
            return;
        }
        try self.records.append(try MemoryRecord.init(self.allocator, owner_agent, scope, key, value, tags));
    }

    pub fn putText(
        self: *MemoryFabric,
        owner_agent: ?[]const u8,
        scope: MemoryScope,
        key: []const u8,
        value: []const u8,
        tags: []const []const u8,
    ) !void {
        var dv = DataValue{ .text = try self.allocator.dupe(u8, value) };
        defer dv.deinit(self.allocator);
        try self.put(owner_agent, scope, key, dv, tags);
    }

    pub fn findLatestIndex(self: *MemoryFabric, key: []const u8) ?usize {
        var i: usize = self.records.items.len;
        while (i > 0) {
            i -= 1;
            if (std.mem.eql(u8, self.records.items[i].key, key)) {
                return i;
            }
        }
        return null;
    }

    pub fn getLatest(self: *MemoryFabric, key: []const u8) ?*MemoryRecord {
        if (self.findLatestIndex(key)) |idx| {
            self.records.items[idx].hits += 1;
            return &self.records.items[idx];
        }
        return null;
    }

    pub fn search(self: *MemoryFabric, allocator: Allocator, query: []const u8, limit: usize) !ArrayList(MemorySearchHit) {
        var hits = ArrayList(MemorySearchHit).init(allocator);
        errdefer {
            for (hits.items) |*hit| hit.deinit(allocator);
            hits.deinit();
        }

        for (self.records.items) |*record| {
            const score_value = record.score(query);
            if (score_value == 0) continue;
            const preview = try record.value.toOwnedText(allocator);
            try hits.append(.{
                .key = try allocator.dupe(u8, record.key),
                .preview = preview,
                .scope = record.scope,
                .score_value = score_value,
            });
            record.hits += 1;
        }

        if (hits.items.len > 1) {
            var i: usize = 0;
            while (i < hits.items.len) : (i += 1) {
                var best = i;
                var j = i + 1;
                while (j < hits.items.len) : (j += 1) {
                    if (hits.items[j].score_value > hits.items[best].score_value) {
                        best = j;
                    }
                }
                if (best != i) {
                    const temp = hits.items[i];
                    hits.items[i] = hits.items[best];
                    hits.items[best] = temp;
                }
            }
        }

        while (hits.items.len > limit) {
            var tail = hits.pop();
            tail.deinit(allocator);
        }

        return hits;
    }

    pub fn renderSearch(self: *MemoryFabric, allocator: Allocator, query: []const u8, limit: usize) ![]u8 {
        var hits = try self.search(allocator, query, limit);
        defer {
            for (hits.items) |*hit| hit.deinit(allocator);
            hits.deinit();
        }

        var out = ArrayList(u8).init(allocator);
        errdefer out.deinit();

        if (hits.items.len == 0) {
            try out.writeAll("no-results");
            return out.toOwnedSlice();
        }

        for (hits.items, 0..) |hit, idx| {
            try out.writer().print("{d}|{s}|{s}|{s}\n", .{
                idx,
                hit.key,
                hit.scope.toString(),
                hit.preview,
            });
        }

        return out.toOwnedSlice();
    }
};

pub const Agent = struct {
    allocator: Allocator,
    id: []u8,
    alias: []u8,
    role: AgentRole,
    state: AgentState,
    goals: ArrayList([]u8),
    inbox: ArrayList(Event),
    success_count: u64,
    failure_count: u64,
    autonomy_level: f64,
    strategy_version: u32,
    reflection_note: []u8,
    created_at_ms: i64,
    updated_at_ms: i64,

    pub fn init(allocator: Allocator, id: []const u8, alias: []const u8, role: AgentRole) !Agent {
        return .{
            .allocator = allocator,
            .id = try allocator.dupe(u8, id),
            .alias = try allocator.dupe(u8, alias),
            .role = role,
            .state = .idle,
            .goals = ArrayList([]u8).init(allocator),
            .inbox = ArrayList(Event).init(allocator),
            .success_count = 0,
            .failure_count = 0,
            .autonomy_level = 0.5,
            .strategy_version = 1,
            .reflection_note = try allocator.dupe(u8, "initialized"),
            .created_at_ms = std.time.milliTimestamp(),
            .updated_at_ms = std.time.milliTimestamp(),
        };
    }

    pub fn deinit(self: *Agent) void {
        self.allocator.free(self.id);
        self.allocator.free(self.alias);
        for (self.goals.items) |goal| self.allocator.free(goal);
        self.goals.deinit();
        for (self.inbox.items) |*event| event.deinit(self.allocator);
        self.inbox.deinit();
        self.allocator.free(self.reflection_note);
    }

    pub fn addGoal(self: *Agent, goal: []const u8) !void {
        try self.goals.append(try self.allocator.dupe(u8, goal));
        self.updated_at_ms = std.time.milliTimestamp();
    }

    pub fn enqueue(self: *Agent, event: Event) !void {
        try self.inbox.append(event);
        self.updated_at_ms = std.time.milliTimestamp();
    }

    pub fn setReflection(self: *Agent, note: []const u8) !void {
        self.allocator.free(self.reflection_note);
        self.reflection_note = try self.allocator.dupe(u8, note);
        self.updated_at_ms = std.time.milliTimestamp();
    }

    pub fn adapt(self: *Agent) !void {
        const total = self.success_count + self.failure_count;
        var success_ratio: f64 = 0.5;
        if (total > 0) {
            success_ratio = @as(f64, @floatFromInt(self.success_count)) / @as(f64, @floatFromInt(total));
        }
        if (success_ratio >= 0.8) {
            self.autonomy_level = @min(1.0, self.autonomy_level + 0.05);
        } else if (success_ratio < 0.4) {
            self.autonomy_level = @max(0.1, self.autonomy_level - 0.08);
        }
        self.strategy_version += 1;
        self.state = .reflecting;
        var text = ArrayList(u8).init(self.allocator);
        errdefer text.deinit();
        try text.writer().print("strategy-v{d}|success={d}|failure={d}|autonomy={d:.3}", .{
            self.strategy_version,
            self.success_count,
            self.failure_count,
            self.autonomy_level,
        });
        try self.setReflection(text.items);
        text.deinit();
        self.state = .idle;
    }
};

pub const AgentRuntime = struct {
    allocator: Allocator,
    agents: StringHashMap(*Agent),
    log: ArrayList(RuntimeLogEntry),
    memory: *MemoryFabric,

    pub fn init(allocator: Allocator, memory: *MemoryFabric) AgentRuntime {
        return .{
            .allocator = allocator,
            .agents = StringHashMap(*Agent).init(allocator),
            .log = ArrayList(RuntimeLogEntry).init(allocator),
            .memory = memory,
        };
    }

    pub fn deinit(self: *AgentRuntime) void {
        var it = self.agents.iterator();
        while (it.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
            entry.value_ptr.*.deinit();
            self.allocator.destroy(entry.value_ptr.*);
        }
        self.agents.deinit();
        for (self.log.items) |*entry| entry.deinit(self.allocator);
        self.log.deinit();
    }

    pub fn appendLog(self: *AgentRuntime, phase: []const u8, subject: []const u8, detail: []const u8, status: ExecutionStatus) !void {
        try self.log.append(try RuntimeLogEntry.init(self.allocator, phase, subject, detail, status));
    }

    pub fn createAgent(self: *AgentRuntime, id: []const u8, alias: []const u8, role: AgentRole) !*Agent {
        if (self.agents.contains(id)) return error.AgentAlreadyExists;
        const key = try self.allocator.dupe(u8, id);
        errdefer self.allocator.free(key);
        const agent_ptr = try self.allocator.create(Agent);
        errdefer self.allocator.destroy(agent_ptr);
        agent_ptr.* = try Agent.init(self.allocator, id, alias, role);
        errdefer agent_ptr.deinit();
        try self.agents.put(key, agent_ptr);
        try self.appendLog("runtime.create_agent", id, role.toString(), .succeeded);
        return agent_ptr;
    }

    pub fn getAgent(self: *AgentRuntime, id: []const u8) ?*Agent {
        return self.agents.get(id);
    }

    pub fn emit(self: *AgentRuntime, event: Event) !void {
        const target_agent = self.agents.get(event.target) orelse return error.UnknownAgent;
        try target_agent.enqueue(try event.clone(self.allocator));
        try self.appendLog("runtime.emit", event.target, event.kind.toString(), .succeeded);
    }

    pub fn runAgentCycle(self: *AgentRuntime, id: []const u8) !void {
        const agent = self.agents.get(id) orelse return error.UnknownAgent;
        agent.state = .busy;
        defer agent.state = .idle;

        var processed: usize = 0;
        while (agent.inbox.items.len > 0) {
            var event = agent.inbox.orderedRemove(0);
            defer event.deinit(self.allocator);

            var key_buf = ArrayList(u8).init(self.allocator);
            defer key_buf.deinit();

            try key_buf.writer().print("event:{s}:{d}", .{ agent.id, std.time.milliTimestamp() });

            const tags = [_][]const u8{
                event.kind.toString(),
                agent.role.toString(),
                agent.state.toString(),
            };

            try self.memory.putText(
                agent.id,
                .operational,
                key_buf.items,
                event.payload,
                &tags,
            );

            switch (event.kind) {
                .task => {
                    processed += 1;
                    agent.success_count += 1;
                },
                .group_message => {
                    processed += 1;
                },
                .escalation => {
                    processed += 1;
                    agent.failure_count += 1;
                    agent.state = .degraded;
                },
                .reflection => {
                    processed += 1;
                    agent.state = .reflecting;
                },
                .capability_result => {
                    processed += 1;
                    agent.success_count += 1;
                },
                .memory_sync => {
                    processed += 1;
                },
                .heartbeat => {
                    processed += 1;
                },
            }

            try self.appendLog("runtime.run_cycle", agent.id, event.kind.toString(), .succeeded);
        }

        var note = ArrayList(u8).init(self.allocator);
        defer note.deinit();
        try note.writer().print("processed={d}|autonomy={d:.3}", .{ processed, agent.autonomy_level });
        try agent.setReflection(note.items);
        try agent.adapt();
    }

    pub fn runAll(self: *AgentRuntime) !void {
        var names = ArrayList([]u8).init(self.allocator);
        defer {
            for (names.items) |name| self.allocator.free(name);
            names.deinit();
        }

        var it = self.agents.iterator();
        while (it.next()) |entry| {
            try names.append(try self.allocator.dupe(u8, entry.key_ptr.*));
        }

        for (names.items) |name| {
            try self.runAgentCycle(name);
        }
    }
};

