    pub fn addMember(self: *ChatRoom, id: []const u8) !void {
        for (self.members.items) |member| {
            if (std.mem.eql(u8, member, id)) return;
        }
        try self.members.append(try self.allocator.dupe(u8, id));
    }
};

pub const AgentMesh = struct {
    allocator: Allocator,
    runtime: *AgentRuntime,
    rooms: StringHashMap(*ChatRoom),

    pub fn init(allocator: Allocator, runtime: *AgentRuntime) AgentMesh {
        return .{
            .allocator = allocator,
            .runtime = runtime,
            .rooms = StringHashMap(*ChatRoom).init(allocator),
        };
    }

    pub fn deinit(self: *AgentMesh) void {
        var it = self.rooms.iterator();
        while (it.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
            entry.value_ptr.*.deinit();
            self.allocator.destroy(entry.value_ptr.*);
        }
        self.rooms.deinit();
    }

    pub fn createRoom(self: *AgentMesh, room_name: []const u8) !void {
        if (self.rooms.contains(room_name)) return;
        const key = try self.allocator.dupe(u8, room_name);
        errdefer self.allocator.free(key);
        const room_ptr = try self.allocator.create(ChatRoom);
        errdefer self.allocator.destroy(room_ptr);
        room_ptr.* = try ChatRoom.init(self.allocator, room_name);
        try self.rooms.put(key, room_ptr);
        try self.runtime.appendLog("mesh.create_room", room_name, "created", .succeeded);
    }

    pub fn join(self: *AgentMesh, room_name: []const u8, agent_id: []const u8) !void {
        const room = self.rooms.get(room_name) orelse return error.UnknownRoom;
        _ = self.runtime.getAgent(agent_id) orelse return error.UnknownAgent;
        try room.addMember(agent_id);
        try self.runtime.appendLog("mesh.join", agent_id, room_name, .succeeded);
    }

    pub fn sendGroupMessage(self: *AgentMesh, room_name: []const u8, sender: []const u8, message: []const u8) !void {
        const room = self.rooms.get(room_name) orelse return error.UnknownRoom;
        for (room.members.items) |member| {
            if (std.mem.eql(u8, member, sender)) continue;
            var event = try Event.init(self.allocator, .group_message, sender, member, message);
            defer event.deinit(self.allocator);
            try self.runtime.emit(event);
        }
        try room.transcript.append(try Event.init(self.allocator, .group_message, sender, room_name, message));
        try self.runtime.appendLog("mesh.group_message", sender, room_name, .succeeded);
    }

    pub fn escalate(self: *AgentMesh, source: []const u8, target: []const u8, payload: []const u8) !void {
        var event = try Event.init(self.allocator, .escalation, source, target, payload);
        defer event.deinit(self.allocator);
        try self.runtime.emit(event);
        try self.runtime.appendLog("mesh.escalate", target, payload, .succeeded);
    }
};

pub const EdgeNode = struct {
