    latency_ms: i64,
    reliability: f64,
    autonomy_level: f64,
    status: EdgeNodeStatus,
    tags: ArrayList([]u8),
    deployed_agents: ArrayList([]u8),

    pub fn init(
        allocator: Allocator,
        id: []const u8,
        zone: []const u8,
        capacity_total: i64,
        latency_ms: i64,
        reliability: f64,
        autonomy_level: f64,
    ) !EdgeNode {
        return .{
            .allocator = allocator,
            .id = try allocator.dupe(u8, id),
            .zone = try allocator.dupe(u8, zone),
            .capacity_total = capacity_total,
            .capacity_used = 0,
            .latency_ms = latency_ms,
            .reliability = reliability,
            .autonomy_level = autonomy_level,
            .status = .ready,
            .tags = ArrayList([]u8).init(allocator),
            .deployed_agents = ArrayList([]u8).init(allocator),
        };
    }

    pub fn deinit(self: *EdgeNode) void {
        self.allocator.free(self.id);
        self.allocator.free(self.zone);
        for (self.tags.items) |tag| self.allocator.free(tag);
        self.tags.deinit();
        for (self.deployed_agents.items) |agent| self.allocator.free(agent);
        self.deployed_agents.deinit();
    }

    pub fn addTag(self: *EdgeNode, tag: []const u8) !void {
        for (self.tags.items) |existing| {
            if (std.mem.eql(u8, existing, tag)) return;
        }
        try self.tags.append(try self.allocator.dupe(u8, tag));
    }

    pub fn availableCapacity(self: *const EdgeNode) i64 {
        return self.capacity_total - self.capacity_used;
    }

    pub fn hasTag(self: *const EdgeNode, tag: []const u8) bool {
        for (self.tags.items) |existing| {
            if (std.mem.eql(u8, existing, tag)) return true;
        }
        return false;
    }
};

pub const CloudPlan = struct {
    workload_id: []const u8,
    priority: i64,
    requested_capacity: i64,
    preferred_zone: ?[]const u8,
    required_tag: ?[]const u8,
    agent_id: ?[]const u8,
};

pub const CloudAssignment = struct {
    edge_id: []u8,
    score_value: f64,

    pub fn deinit(self: *CloudAssignment, allocator: Allocator) void {
        allocator.free(self.edge_id);
    }
};

pub const CloudEdgeOrchestrator = struct {
    allocator: Allocator,
    nodes: ArrayList(EdgeNode),

    pub fn init(allocator: Allocator) CloudEdgeOrchestrator {
        return .{
            .allocator = allocator,
            .nodes = ArrayList(EdgeNode).init(allocator),
        };
    }

    pub fn deinit(self: *CloudEdgeOrchestrator) void {
        for (self.nodes.items) |*node| node.deinit();
        self.nodes.deinit();
    }

    pub fn registerNode(
        self: *CloudEdgeOrchestrator,
        id: []const u8,
        zone: []const u8,
        capacity_total: i64,
        latency_ms: i64,
        reliability: f64,
        autonomy_level: f64,
        tags: []const []const u8,
    ) !void {
        for (self.nodes.items) |*node| {
            if (std.mem.eql(u8, node.id, id)) {
                return error.EdgeNodeAlreadyExists;
            }
        }

        var node = try EdgeNode.init(
            self.allocator,
            id,
            zone,
            capacity_total,
            latency_ms,
            reliability,
            autonomy_level,
        );
        errdefer node.deinit();

        for (tags) |tag| {
            try node.addTag(tag);
        }

        try self.nodes.append(node);
    }

    fn scoreNode(self: *CloudEdgeOrchestrator, node: *const EdgeNode, plan: CloudPlan) f64 {
        _ = self;

        if (node.status == .offline) return -1e9;
        if (node.availableCapacity() < plan.requested_capacity) return -1e9;
        if (plan.preferred_zone) |zone| {
            if (!std.mem.eql(u8, node.zone, zone)) {
                return -1000.0 + node.reliability;
            }
        }
        if (plan.required_tag) |tag| {
            if (!node.hasTag(tag)) return -1e9;
        }

        const capacity_score = @as(f64, @floatFromInt(node.availableCapacity()));
        const latency_penalty = @as(f64, @floatFromInt(node.latency_ms)) * 0.2;
        const reliability_bonus = node.reliability * 100.0;
        const autonomy_bonus = node.autonomy_level * 50.0;
        const priority_bonus = @as(f64, @floatFromInt(plan.priority)) * 5.0;

        return capacity_score + reliability_bonus + autonomy_bonus + priority_bonus - latency_penalty;
    }

    pub fn planAssignment(self: *CloudEdgeOrchestrator, plan: CloudPlan) !CloudAssignment {
        if (self.nodes.items.len == 0) return error.NoEdgeNodes;

        var best_idx: ?usize = null;
        var best_score: f64 = -1e18;

        for (self.nodes.items, 0..) |*node, idx| {
            const score_value = self.scoreNode(node, plan);
            if (score_value > best_score) {
                best_score = score_value;
                best_idx = idx;
            }
        }

        if (best_idx == null or best_score < -1e8) return error.NoViableAssignment;

        return .{
            .edge_id = try self.allocator.dupe(u8, self.nodes.items[best_idx.?].id),
            .score_value = best_score,
        };
    }

    pub fn deployAgent(self: *CloudEdgeOrchestrator, edge_id: []const u8, agent_id: []const u8, requested_capacity: i64) !void {
        for (self.nodes.items) |*node| {
            if (!std.mem.eql(u8, node.id, edge_id)) continue;
            if (node.availableCapacity() < requested_capacity) return error.InsufficientEdgeCapacity;
            node.capacity_used += requested_capacity;
            try node.deployed_agents.append(try self.allocator.dupe(u8, agent_id));
            if (node.availableCapacity() == 0) {
                node.status = .busy;
            } else {
                node.status = .ready;
            }
            return;
        }
        return error.UnknownEdgeNode;
    }

    pub fn rebalance(self: *CloudEdgeOrchestrator) void {
        for (self.nodes.items) |*node| {
            if (node.status == .offline) continue;
            const usage = if (node.capacity_total == 0) 1.0 else @as(f64, @floatFromInt(node.capacity_used)) / @as(f64, @floatFromInt(node.capacity_total));
            if (usage > 0.95 and node.reliability < 0.9) {
                node.status = .degraded;
            } else if (usage > 0.99) {
                node.status = .busy;
            } else {
                node.status = .ready;
            }
        }
    }
};

pub const ExecutionContext = struct {
    allocator: Allocator,
    runtime: *AgentRuntime,
    mesh: *AgentMesh,
    memory: *MemoryFabric,
    orchestrator: *CloudEdgeOrchestrator,
    variables: StringHashMap(DataValue),
    output_log: ArrayList([]u8),

    pub fn init(
        allocator: Allocator,
        runtime: *AgentRuntime,
        mesh: *AgentMesh,
        memory: *MemoryFabric,
        orchestrator: *CloudEdgeOrchestrator,
    ) ExecutionContext {
        return .{
            .allocator = allocator,
            .runtime = runtime,
            .mesh = mesh,
            .memory = memory,
            .orchestrator = orchestrator,
            .variables = StringHashMap(DataValue).init(allocator),
            .output_log = ArrayList([]u8).init(allocator),
        };
    }

    pub fn deinit(self: *ExecutionContext) void {
        var it = self.variables.iterator();
        while (it.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
            entry.value_ptr.*.deinit(self.allocator);
        }
        self.variables.deinit();

        for (self.output_log.items) |item| self.allocator.free(item);
        self.output_log.deinit();
    }

    pub fn setVar(self: *ExecutionContext, name: []const u8, value: DataValue) !void {
        const gop = try self.variables.getOrPut(try self.allocator.dupe(u8, name));
        if (gop.found_existing) {
            self.allocator.free(name);
        }
        if (gop.found_existing) {
            gop.value_ptr.*.deinit(self.allocator);
            gop.value_ptr.* = try value.clone(self.allocator);
        } else {
            gop.value_ptr.* = try value.clone(self.allocator);
        }
    }

    pub fn getVar(self: *ExecutionContext, name: []const u8) ?*DataValue {
        return self.variables.getPtr(name);
    }

    pub fn appendOutput(self: *ExecutionContext, text: []const u8) !void {
        try self.output_log.append(try self.allocator.dupe(u8, text));
    }

    pub fn renderOutput(self: *ExecutionContext) ![]u8 {
        var list = ArrayList(u8).init(self.allocator);
        errdefer list.deinit();
        for (self.output_log.items) |entry| {
            try list.writeAll(entry);
            try list.writeByte('\n');
        }
        return list.toOwnedSlice();
    }
};

pub const CapabilityHandler = *const fn (ctx: *ExecutionContext, input: []const u8, output: *ArrayList(u8)) anyerror!void;

pub const CapabilitySpec = struct {
    name: []u8,
    kind: CapabilityKind,
    version: u32,
    deterministic: bool,
    handler: CapabilityHandler,

    pub fn deinit(self: *CapabilitySpec, allocator: Allocator) void {
        allocator.free(self.name);
    }
};

pub const CapabilityRegistry = struct {
    allocator: Allocator,
    specs: ArrayList(CapabilitySpec),
    index: StringHashMap(usize),

    pub fn init(allocator: Allocator) CapabilityRegistry {
        return .{
            .allocator = allocator,
            .specs = ArrayList(CapabilitySpec).init(allocator),
            .index = StringHashMap(usize).init(allocator),
        };
    }

    pub fn deinit(self: *CapabilityRegistry) void {
        for (self.specs.items) |*spec| spec.deinit(self.allocator);
        self.specs.deinit();
        var it = self.index.iterator();
        while (it.next()) |entry| self.allocator.free(entry.key_ptr.*);
        self.index.deinit();
    }

    pub fn register(
        self: *CapabilityRegistry,
        name: []const u8,
        kind: CapabilityKind,
        version: u32,
        deterministic: bool,
        handler: CapabilityHandler,
    ) !void {
        if (self.index.contains(name)) return error.CapabilityAlreadyExists;

        try self.specs.append(.{
            .name = try self.allocator.dupe(u8, name),
            .kind = kind,
            .version = version,
            .deterministic = deterministic,
            .handler = handler,
        });

        const key = try self.allocator.dupe(u8, name);
        errdefer self.allocator.free(key);
        try self.index.put(key, self.specs.items.len - 1);
    }

    pub fn execute(self: *CapabilityRegistry, ctx: *ExecutionContext, name: []const u8, input: []const u8) ![]u8 {
        const idx = self.index.get(name) orelse return error.UnknownCapability;
        const spec = self.specs.items[idx];
        var out = ArrayList(u8).init(self.allocator);
        errdefer out.deinit();
        try spec.handler(ctx, input, &out);
        const result = try out.toOwnedSlice();
        try ctx.appendOutput(result);
        return result;
    }
};

pub const WorkflowNode = struct {
    allocator: Allocator,
