    agent_id: ?[]u8,
    input_template: ?[]u8,
    condition_key: ?[]u8,
    next: ArrayList([]u8),
    fail_next: ?[]u8,

    pub fn init(allocator: Allocator, id: []const u8, kind: WorkflowNodeKind) !WorkflowNode {
        return .{
            .allocator = allocator,
            .id = try allocator.dupe(u8, id),
            .kind = kind,
            .capability_name = null,
            .agent_id = null,
            .input_template = null,
            .condition_key = null,
            .next = ArrayList([]u8).init(allocator),
            .fail_next = null,
        };
    }

    pub fn deinit(self: *WorkflowNode) void {
        self.allocator.free(self.id);
        if (self.capability_name) |v| self.allocator.free(v);
        if (self.agent_id) |v| self.allocator.free(v);
        if (self.input_template) |v| self.allocator.free(v);
