        self.input_template = try self.allocator.dupe(u8, input);
    }

    pub fn setConditionKey(self: *WorkflowNode, key: []const u8) !void {
        if (self.condition_key) |old| self.allocator.free(old);
        self.condition_key = try self.allocator.dupe(u8, key);
    }

    pub fn addNext(self: *WorkflowNode, id: []const u8) !void {
        try self.next.append(try self.allocator.dupe(u8, id));
    }

    pub fn setFailNext(self: *WorkflowNode, id: []const u8) !void {
