pub const WorkflowDefinition = struct {
    allocator: Allocator,
    name: []u8,
    nodes: ArrayList(WorkflowNode),
    node_index: StringHashMap(usize),
    start_node: ?[]u8,

    pub fn init(allocator: Allocator, name: []const u8) !WorkflowDefinition {
        return .{
            .allocator = allocator,
            .name = try allocator.dupe(u8, name),
            .nodes = ArrayList(WorkflowNode).init(allocator),
            .node_index = StringHashMap(usize).init(allocator),
            .start_node = null,
        };
    }

    pub fn deinit(self: *WorkflowDefinition) void {
        self.allocator.free(self.name);
        if (self.start_node) |node| self.allocator.free(node);
        for (self.nodes.items) |*node| node.deinit();
        self.nodes.deinit();

        var it = self.node_index.iterator();
        while (it.next()) |entry| self.allocator.free(entry.key_ptr.*);
        self.node_index.deinit();
    }

    pub fn addNode(self: *WorkflowDefinition, node: WorkflowNode) !void {
        if (self.node_index.contains(node.id)) return error.DuplicateWorkflowNode;

        const key = try self.allocator.dupe(u8, node.id);
        errdefer self.allocator.free(key);

        if (node.kind == .start) {
            if (self.start_node) |old| self.allocator.free(old);
            self.start_node = try self.allocator.dupe(u8, node.id);
        }

        try self.nodes.append(node);
        try self.node_index.put(key, self.nodes.items.len - 1);
    }

    pub fn getNode(self: *WorkflowDefinition, id: []const u8) ?*WorkflowNode {
        const idx = self.node_index.get(id) orelse return null;
        return &self.nodes.items[idx];
    }
};

pub const WorkflowEngine = struct {
    allocator: Allocator,
    workflows: StringHashMap(*WorkflowDefinition),
    registry: *CapabilityRegistry,

    pub fn init(allocator: Allocator, registry: *CapabilityRegistry) WorkflowEngine {
        return .{
            .allocator = allocator,
            .workflows = StringHashMap(*WorkflowDefinition).init(allocator),
            .registry = registry,
        };
    }

    pub fn deinit(self: *WorkflowEngine) void {
        var it = self.workflows.iterator();
        while (it.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
            entry.value_ptr.*.deinit();
            self.allocator.destroy(entry.value_ptr.*);
        }
        self.workflows.deinit();
    }

    pub fn register(self: *WorkflowEngine, workflow: WorkflowDefinition) !void {
        if (self.workflows.contains(workflow.name)) return error.WorkflowAlreadyExists;
        const key = try self.allocator.dupe(u8, workflow.name);
        errdefer self.allocator.free(key);
        const ptr = try self.allocator.create(WorkflowDefinition);
        errdefer self.allocator.destroy(ptr);
        ptr.* = workflow;
        try self.workflows.put(key, ptr);
    }

    fn resolveInput(ctx: *ExecutionContext, template: ?[]const u8) ![]u8 {
        if (template == null) return ctx.allocator.dupe(u8, "");
        const raw = template.?;
        if (raw.len > 1 and raw[0] == '$') {
            const key = raw[1..];
            if (ctx.getVar(key)) |value| {
                return value.toOwnedText(ctx.allocator);
            }
            return ctx.allocator.dupe(u8, "");
        }
        return ctx.allocator.dupe(u8, raw);
    }

    fn enqueueOwned(queue: *ArrayList([]u8), allocator: Allocator, text: []const u8) !void {
        try queue.append(try allocator.dupe(u8, text));
    }

    pub fn execute(self: *WorkflowEngine, ctx: *ExecutionContext, name: []const u8) !void {
        const wf = self.workflows.get(name) orelse return error.UnknownWorkflow;
        const start_id = wf.start_node orelse return error.MissingWorkflowStart;

        var queue = ArrayList([]u8).init(self.allocator);
        defer {
            for (queue.items) |item| self.allocator.free(item);
            queue.deinit();
        }

        try enqueueOwned(&queue, self.allocator, start_id);

        var steps: usize = 0;
        while (queue.items.len > 0) {
            var current_id = queue.orderedRemove(0);
            defer self.allocator.free(current_id);

            const node = wf.getNode(current_id) orelse return error.UnknownWorkflowNode;
            steps += 1;
            if (steps > 4096) return error.WorkflowStepLimitExceeded;

            switch (node.kind) {
                .start => {
                    for (node.next.items) |next_id| try enqueueOwned(&queue, self.allocator, next_id);
                },
                .capability => {
                    const capability_name = node.capability_name orelse return error.MissingCapabilityName;
                    const input = try resolveInput(ctx, node.input_template);
                    defer ctx.allocator.free(input);

                    const result = self.registry.execute(ctx, capability_name, input) catch |err| {
                        if (node.fail_next) |fail_id| {
                            try enqueueOwned(&queue, self.allocator, fail_id);
                            continue;
                        }
                        return err;
                    };
                    defer self.registry.allocator.free(result);

                    try ctx.runtime.appendLog("workflow.capability", node.id, capability_name, .succeeded);
                    for (node.next.items) |next_id| try enqueueOwned(&queue, self.allocator, next_id);
                },
                .agent => {
                    const agent_id = node.agent_id orelse return error.MissingAgentId;
                    const input = try resolveInput(ctx, node.input_template);
                    defer ctx.allocator.free(input);

                    var event = try Event.init(ctx.allocator, .task, "workflow", agent_id, input);
                    defer event.deinit(ctx.allocator);

                    try ctx.runtime.emit(event);
                    try ctx.runtime.runAgentCycle(agent_id);
                    try ctx.runtime.appendLog("workflow.agent", node.id, agent_id, .succeeded);

                    for (node.next.items) |next_id| try enqueueOwned(&queue, self.allocator, next_id);
                },
                .decision => {
                    const key = node.condition_key orelse return error.MissingConditionKey;
                    const truth = if (ctx.getVar(key)) |value| value.isTruthy() else false;
                    if (truth) {
                        if (node.next.items.len > 0) try enqueueOwned(&queue, self.allocator, node.next.items[0]);
                    } else {
                        if (node.fail_next) |fail_id| try enqueueOwned(&queue, self.allocator, fail_id);
                    }
                    try ctx.runtime.appendLog("workflow.decision", node.id, key, .succeeded);
                },
                .parallel => {
                    for (node.next.items) |next_id| try enqueueOwned(&queue, self.allocator, next_id);
                    try ctx.runtime.appendLog("workflow.parallel", node.id, "fanout", .succeeded);
                },
                .join => {
                    for (node.next.items) |next_id| try enqueueOwned(&queue, self.allocator, next_id);
                    try ctx.runtime.appendLog("workflow.join", node.id, "join", .succeeded);
                },
                .end => {
                    try ctx.runtime.appendLog("workflow.end", node.id, "completed", .succeeded);
                },
            }
        }
    }
};

fn capabilityEcho(ctx: *ExecutionContext, input: []const u8, output: *ArrayList(u8)) !void {
    _ = ctx;
    try output.writeAll(input);
}

fn capabilitySetVar(ctx: *ExecutionContext, input: []const u8, output: *ArrayList(u8)) !void {
    const eq = std.mem.indexOfScalar(u8, input, '=') orelse return error.InvalidCapabilityInput;
    const key = trimSpace(input[0..eq]);
    const value_text = trimSpace(input[eq + 1 ..]);
    var value = try parseValueAuto(ctx.allocator, value_text);
    defer value.deinit(ctx.allocator);
    try ctx.setVar(key, value);
    try output.writer().print("set:{s}", .{key});
}

fn capabilityMemoryPut(ctx: *ExecutionContext, input: []const u8, output: *ArrayList(u8)) !void {
    var it = std.mem.splitScalar(u8, input, '|');
    const scope_text = it.next() orelse return error.InvalidCapabilityInput;
    const owner = it.next() orelse return error.InvalidCapabilityInput;
    const key = it.next() orelse return error.InvalidCapabilityInput;
    const value = it.next() orelse return error.InvalidCapabilityInput;

    const tags_buf = [_][]const u8{ "capability", "memory_put" };

    try ctx.memory.putText(
        if (owner.len == 0) null else owner,
        MemoryScope.parse(scope_text),
        key,
        value,
        &tags_buf,
    );

    try output.writer().print("memory-put:{s}", .{key});
}

