fn capabilityEdgeRegister(ctx: *ExecutionContext, input: []const u8, output: *ArrayList(u8)) !void {
    var it = std.mem.splitScalar(u8, input, '|');
    const id = it.next() orelse return error.InvalidCapabilityInput;
    const zone = it.next() orelse return error.InvalidCapabilityInput;
    const capacity_text = it.next() orelse return error.InvalidCapabilityInput;
    const latency_text = it.next() orelse return error.InvalidCapabilityInput;
    const reliability_text = it.next() orelse return error.InvalidCapabilityInput;
    const autonomy_text = it.next() orelse return error.InvalidCapabilityInput;
    const tags_text = it.next() orelse "";

    const capacity_total = try std.fmt.parseInt(i64, trimSpace(capacity_text), 10);
    const latency_ms = try std.fmt.parseInt(i64, trimSpace(latency_text), 10);
    const reliability = try std.fmt.parseFloat(f64, trimSpace(reliability_text));
    const autonomy = try std.fmt.parseFloat(f64, trimSpace(autonomy_text));

    var tags = ArrayList([]const u8).init(ctx.allocator);
    defer tags.deinit();

    var tags_it = std.mem.splitScalar(u8, tags_text, ',');
    while (tags_it.next()) |tag| {
        const clean = trimSpace(tag);
        if (clean.len > 0) try tags.append(clean);
    }

    try ctx.orchestrator.registerNode(
        id,
        zone,
        capacity_total,
        latency_ms,
        reliability,
        autonomy,
        tags.items,
    );

    try output.writer().print("edge-registered:{s}", .{id});
}

fn capabilityEdgeAssign(ctx: *ExecutionContext, input: []const u8, output: *ArrayList(u8)) !void {
    var it = std.mem.splitScalar(u8, input, '|');
    const workload_id = it.next() orelse return error.InvalidCapabilityInput;
    const priority_text = it.next() orelse return error.InvalidCapabilityInput;
    const request_text = it.next() orelse return error.InvalidCapabilityInput;
    const zone = it.next() orelse "";
    const tag = it.next() orelse "";
    const agent_id = it.next() orelse "";

    const plan = CloudPlan{
        .workload_id = workload_id,
        .priority = try std.fmt.parseInt(i64, trimSpace(priority_text), 10),
        .requested_capacity = try std.fmt.parseInt(i64, trimSpace(request_text), 10),
        .preferred_zone = if (trimSpace(zone).len == 0) null else trimSpace(zone),
        .required_tag = if (trimSpace(tag).len == 0) null else trimSpace(tag),
        .agent_id = if (trimSpace(agent_id).len == 0) null else trimSpace(agent_id),
    };

    var assignment = try ctx.orchestrator.planAssignment(plan);
    defer assignment.deinit(ctx.allocator);

    if (plan.agent_id) |id| {
        try ctx.orchestrator.deployAgent(assignment.edge_id, id, plan.requested_capacity);
    }

    try output.writer().print("edge-assignment:{s}:{s}:{d:.3}", .{
        plan.workload_id,
        assignment.edge_id,
        assignment.score_value,
    });
}

fn registerBuiltins(registry: *CapabilityRegistry) !void {
    try registry.register("echo", .system, 1, true, capabilityEcho);
    try registry.register("set_var", .system, 1, true, capabilitySetVar);
    try registry.register("memory_put", .memory, 1, true, capabilityMemoryPut);
    try registry.register("memory_search", .memory, 1, false, capabilityMemorySearch);
    try registry.register("spawn_agent", .system, 1, true, capabilitySpawnAgent);
    try registry.register("room_create", .communication, 1, true, capabilityRoomCreate);
    try registry.register("room_join", .communication, 1, true, capabilityRoomJoin);
    try registry.register("room_message", .communication, 1, false, capabilityRoomMessage);
    try registry.register("edge_register", .orchestration, 1, true, capabilityEdgeRegister);
    try registry.register("edge_assign", .orchestration, 1, false, capabilityEdgeAssign);
}

