        try n.setCapability("edge_register");
        try n.setInput("edge-b|plant-b|70|18|0.96|0.90|assembly,vision");
        try n.addNext("memory-put");
        break :blk n;
    });
    try workflow.addNode(blk: {
        var n = try WorkflowNode.init(allocator, "memory-put", .capability);
        try n.setCapability("memory_put");
        try n.setInput("semantic|planner-1|global_policy|prefer-low-latency");
        try n.addNext("assign");
        break :blk n;
    });
    try workflow.addNode(blk: {
        var n = try WorkflowNode.init(allocator, "assign", .capability);
        try n.setCapability("edge_assign");
        try n.setInput("order-17|5|20|plant-a|vision|edge-1");
        try n.addNext("notify");
        break :blk n;
